package corpus.stacktracepolicy

fun directThreadDump() {
    Thread.dumpStack()
}

fun invokeWithDirectTrace(action: () -> Unit) {
    try {
        action()
    } catch (failure: Exception) {
        failure.printStackTrace()
    }
}

package corpus.stacktracepolicy

fun recordThreadCheckpoint(record: (String) -> Unit) {
    record("thread checkpoint")
}

fun invokeWithControlledTrace(action: () -> Unit, report: (Throwable) -> Unit) {
    try {
        action()
    } catch (failure: Exception) {
        report(failure)
    }
}

