package corpus.stacktracepolicy

private object Thread {
    fun dumpStack(): List<String> = listOf("queued-work")
}

fun queuedWorkNames(): List<String> = Thread.dumpStack()

package corpus.stacktracepolicy

fun invokeWithAliasedTrace(action: () -> Unit) {
    try {
        action()
    } catch (failure: Exception) {
        val alias = failure
        alias.printStackTrace()
    }
}
